import test from 'node:test';import assert from 'node:assert/strict';import {correctProductData} from './product-title-corrections.mjs';
test('triagem82 preserva operação e identidade sem inventar espessura vazão ou rotina de combustível',()=>{for(const [id,titulo] of [['hhnKX4x5l2ab7gguVoYU','Piscina Inflável Pvc Espessa Resistente Família Grande'],['hLiaQWog1dogQ2OpMDSt','Ventilador De Mesa 40cm Turbo NVT-40-BL MONDIAL'],['htLzwGXLZpkVa0eXWdkr','Soprador de folhas lateral Fak260S 2T 26Cc 0,90Hp Carbon Fak cor laranja profissional a gasolina']]){const p={id,titulo,preco:'preservar',linkAfiliado:'https://meli.la/preservar'},x=correctProductData(p);assert.equal(x.preco,p.preco);assert.equal(x.linkAfiliado,p.linkAfiliado);assert.deepEqual(correctProductData(x),x);assert.equal(correctProductData({...p,titulo:'Outro produto',comentario:'manter'}).comentario,'manter');assert.doesNotMatch(x.pros,/oficial|resistência garantida|470.*m³\/h/i);assert.doesNotMatch(x.comentario,/\b\d+:\d+\b|espessura de \d|470\s*m³\/h/i);}});
